exploreUrl:
@js:
var result = [];
java.toast("🔥正在刷新列表,请稍等！");
var push = (title, url, size) => result.push({
    "title": title,
    "url": url,
    "style": {
        "layout_flexGrow": 1,
        "layout_flexBasisPercent": size
    }
});
var baseUrl = "https://www.shacg.com/all.html";
var tag = java.ajax(baseUrl);
if (tag) {
    var a = org.jsoup.Jsoup.parse(tag).select(".class ul li a");
    push("🔥分类小说🔥", null, 1);
    for (var i = 0; i < a.length ; i++) {
        var title = a[i].text();
        var url = a[i].attr("href");
        var size = 0.25;
        title = String(title).replace(/\s/g, "");
        url = String(url).replace(/\.html/,'-{{page}}.html');      
        push(title, url, size);
    }
} else {
  java.toast("🤔列表刷新失败！！！");     
} 
JSON.stringify(result);

ruleSearch.bookList:
div.hot_sale[0:9]
<js>
bookList = result;
h = java.getStringList("a@href", bookList);

ht = h[1].includes("http") ? Array.from(h) : Array.from(h, x => `${source.key}${x}`);

d = java.ajaxAll(ht).map(x => x.body());

$=(b,c)=>java.getString(b,c);

Array.from(bookList,(a,i)=>{
	list={
		name:$("p.title@text",a),
		author:$("p.author.0@text##.*作者：|著",a),
		kind:$(".sort@text",d[i]),
		words:$("",d[i]),
		lastc:$("p.author.1@text##.*更新：",d[i]),
		intro:$(".review@textNodes",d[i]),
		cover:$(".synopsisArea_detail > img@src",d[i]),
		link:$("a@href",a)
		};
		return list
	});
</js>

